```javascript
function metaToPlainObject (meta) {
  const obj = (() => meta.type === 'error' ? new Error() : {})()
  for (let i = 0; i < meta.members.length; i++) {
    const { name, value } = meta.members[i]
    obj[name] = value
  }
  return obj
}
