            else {
                return subsequentPermutations;
            }
        }

        for (var i = 0; i < defaultValues.length; ++i) {
            var value = defaultValues[i];
            var permutation;

            if (subsequentPermutations.length == 0) {
                permutation = {};
                permutation[arg.name] = value + "";
                permutations.push(permutation);
