function range(start, end)
{
    if (arguments.length == 1) {
        var end = start;
        start = 0;
    }

    var r = [];
    if (start < end) {
        while (start != end)
            r.push(start++);
    }
    else {
        while (start != end)
            r.push(start--);
    }
    return r;
}
