            return inf;
        char t1 = id2tag[i1];
        char t2 = id2tag[i2];
        char t3 = id2tag[i3];
        double uni = l1 * tf.freq(s3,t3);
        double bi = div(l2 * tf.get(s2,t2, s3,t3), tf.get(s2,t2));
        double tri = div(l3 * tf.get(s1,t1, s2,t2, s3,t3), tf.get(s1,t1, s2,t2));
        if (uni + bi + tri == 0)
            return inf;
        return Math.log(uni + bi + tri);
